package com.friendgroups;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Owns one social list's groups and their persistence. Two instances exist - one for the friends
 * list and one for the ignore list (see {@link GroupList}) - each persisting under its own config
 * keys within the plugin's config group, so the two are fully independent.
 *
 * Groups belong to a character, not to the RuneLite profile: everything here is stored under the
 * active RuneScape profile (account hash plus game mode), matching the friends and ignore lists
 * themselves, which the game keeps per account. With no character active - logged out, or logging
 * in before the account hash arrives - the store is {@link #isActive() inactive}: it holds no
 * groups and refuses writes rather than dropping them, and is reloaded when the character changes.
 *
 * Mutations arrive from both the Swing EDT (side panel) and the client thread
 * (right-click menu), so writes are serialized on this monitor. Reads from the
 * list script callback go through {@link #groupsFor} instead, which is
 * served by an immutable index rebuilt on every write - the callback runs per
 * row per rebuild and must not contend on a lock.
 */
@Slf4j
class GroupStore
{
	static final int MAX_GROUPS = 20;
	static final int MAX_NAME_LENGTH = 24;

	/**
	 * Order token standing in for the Ungrouped section, so it can be moved among the groups.
	 * Contains control characters {@link #sanitizeName} would never let into a real group name,
	 * so it can never collide with one.
	 */
	static final String UNGROUPED = "�ungrouped�";


	/** Colors handed to new groups, in order. Chosen to stay legible on the dark friends list. */
	private static final int[] PALETTE = {
		0xDC8A00, 0x3FA7D6, 0x59C135, 0xE05263,
		0xB07BEF, 0xEFC94C, 0x4DD0E1, 0xFF8A65,
	};

	private final ConfigManager configManager;
	private final Gson gson;

	/** Which list this store persists, supplying the per-list config keys. */
	private final GroupList list;

	private final List<FriendGroup> groups = new ArrayList<>();
	private final List<Consumer<Boolean>> listeners = new CopyOnWriteArrayList<>();

	private volatile Map<String, List<FriendGroup>> membership = Collections.emptyMap();
	private volatile List<FriendGroup> snapshot = Collections.emptyList();

	private volatile boolean ungroupedCollapsed;

	private volatile boolean offlineCollapsed;

	/** Whether a character is active, so there are groups to serve and somewhere to write them. */
	private volatile boolean active;

	/** Number of groups shown before the Ungrouped section, or null for "last" (the default). */
	private volatile Integer ungroupedOrder;

	GroupStore(ConfigManager configManager, Gson gson, GroupList list)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.list = list;
	}

	/**
	 * Normalizes a name into a stable lookup key. Display names reach us from the
	 * friend container, from widget text, and from config, each with different
	 * casing and separators.
	 */
	static String key(String name)
	{
		return Text.standardize(Text.toJagexName(name));
	}

	static String sanitizeName(String name)
	{
		if (name == null)
		{
			return null;
		}

		final String clean = Text.removeTags(name).replace('<', ' ').replace('>', ' ').trim();
		if (clean.isEmpty())
		{
			return null;
		}
		return clean.length() > MAX_NAME_LENGTH ? clean.substring(0, MAX_NAME_LENGTH).trim() : clean;
	}

	/** @param listener receives true when the change affects the in-game friends list */
	void addListener(Consumer<Boolean> listener)
	{
		listeners.add(listener);
	}

	void removeListener(Consumer<Boolean> listener)
	{
		listeners.remove(listener);
	}

	/** Loads the active character's groups, replacing whatever the store held. */
	synchronized void load()
	{
		groups.clear();
		ungroupedCollapsed = false;
		offlineCollapsed = false;
		ungroupedOrder = null;

		active = configManager.getRSProfileKey() != null;
		if (!active)
		{
			// No character to load. Whoever reloads us on RuneScapeProfileChanged brings the groups back.
			reindex();
			return;
		}

		seedFromShared();

		ungroupedCollapsed = Boolean.TRUE.equals(
			configManager.getRSProfileConfiguration(FriendGroupsConfig.GROUP, list.ungroupedCollapsedKey, Boolean.class));

		offlineCollapsed = Boolean.TRUE.equals(
			configManager.getRSProfileConfiguration(FriendGroupsConfig.GROUP, list.offlineCollapsedKey, Boolean.class));

		ungroupedOrder = configManager.getRSProfileConfiguration(FriendGroupsConfig.GROUP, list.ungroupedOrderKey,
			Integer.class);

		final String json = configManager.getRSProfileConfiguration(FriendGroupsConfig.GROUP, list.groupsKey);
		if (!Strings.isNullOrEmpty(json))
		{
			try
			{
				final List<FriendGroup> loaded = gson.fromJson(json, new TypeToken<List<FriendGroup>>()
				{
				}.getType());

				if (loaded != null)
				{
					for (FriendGroup group : loaded)
					{
						if (group == null || Strings.isNullOrEmpty(group.getName()))
						{
							continue;
						}
						if (group.getMembers() == null)
						{
							group.setMembers(new ArrayList<>());
						}
						groups.add(group);
					}
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Unable to parse saved friend groups, starting with none", e);
			}
		}

		reindex();
	}

	/**
	 * Copies the groups this plugin used to keep once per RuneLite profile - shared by every character
	 * logged in under it - into the character being loaded, the first time that character is seen. So
	 * an existing user keeps their groups wherever they log in, and can then edit them per character.
	 *
	 * <p>The shared copy is left in place as the seed for characters not logged in yet, and is not read
	 * again for a character once it has been seeded, so deleting the seeded groups makes them stay
	 * deleted. Caller holds the lock.
	 */
	private void seedFromShared()
	{
		if (Boolean.TRUE.equals(configManager.getRSProfileConfiguration(FriendGroupsConfig.GROUP, list.seededKey,
			Boolean.class)))
		{
			return;
		}

		// Marked before the copy, so a character with nothing to seed - or one whose copy is cut short -
		// is never seeded a second time over groups they have since edited.
		configManager.setRSProfileConfiguration(FriendGroupsConfig.GROUP, list.seededKey, true);

		// Nothing to seed into a character that already has groups of their own.
		if (configManager.getRSProfileConfiguration(FriendGroupsConfig.GROUP, list.groupsKey) != null)
		{
			return;
		}

		boolean seeded = false;
		for (String key : new String[]{list.groupsKey, list.ungroupedOrderKey, list.ungroupedCollapsedKey,
			list.offlineCollapsedKey})
		{
			// Copied as raw strings: config stores every value as one, so this carries the groups JSON,
			// the ungrouped order and the collapse flags alike without reserializing any of them.
			final String shared = configManager.getConfiguration(FriendGroupsConfig.GROUP, key);
			if (!Strings.isNullOrEmpty(shared))
			{
				configManager.setRSProfileConfiguration(FriendGroupsConfig.GROUP, key, shared);
				seeded = true;
			}
		}

		if (seeded)
		{
			log.debug("Seeded {} groups for this character from the shared groups", list.label);
		}
	}

	/**
	 * Whether a character's groups are loaded. False while no RuneScape profile is active, when the
	 * store serves no groups and ignores every mutation - config writes would be dropped there, and
	 * the groups would belong to no one in particular.
	 */
	boolean isActive()
	{
		return active;
	}

	/**
	 * An immutable view of the groups in display order. Rebuilt on write, so callers
	 * on the menu and render paths can read it without allocating or locking.
	 */
	List<FriendGroup> getGroups()
	{
		return snapshot;
	}

	List<FriendGroup> groupsFor(String friend)
	{
		return membership.getOrDefault(key(friend), Collections.emptyList());
	}

	boolean addGroup(String name)
	{
		final String clean = sanitizeName(name);
		if (!active || clean == null)
		{
			return false;
		}

		synchronized (this)
		{
			if (groups.size() >= MAX_GROUPS || find(clean) != null)
			{
				return false;
			}
			groups.add(new FriendGroup(clean, PALETTE[groups.size() % PALETTE.length]));
			commit();
		}

		fireChanged(true);
		return true;
	}

	boolean renameGroup(String oldName, String newName)
	{
		final String clean = sanitizeName(newName);
		if (!active || clean == null)
		{
			return false;
		}

		synchronized (this)
		{
			final FriendGroup group = find(oldName);
			if (group == null)
			{
				return false;
			}

			final FriendGroup existing = find(clean);
			if (existing != null && existing != group)
			{
				return false;
			}

			group.setName(clean);
			commit();
		}

		fireChanged(true);
		return true;
	}

	void deleteGroup(String name)
	{
		if (!active)
		{
			return;
		}

		synchronized (this)
		{
			final int index = indexOf(name);
			if (index < 0)
			{
				return;
			}
			groups.remove(index);

			// Keep the Ungrouped section in the same relative spot when a group above it goes.
			if (ungroupedOrder != null && index < ungroupedOrder)
			{
				ungroupedOrder = ungroupedOrder - 1;
			}
			commit();
		}

		fireChanged(true);
	}

	void setColor(String name, int color)
	{
		if (!active)
		{
			return;
		}

		synchronized (this)
		{
			final FriendGroup group = find(name);
			if (group == null || group.getColor() == color)
			{
				return;
			}
			group.setColor(color);
			commit();
		}

		fireChanged(true);
	}

	void setCollapsed(String name, boolean collapsed)
	{
		if (!active)
		{
			return;
		}

		synchronized (this)
		{
			final FriendGroup group = find(name);
			if (group == null || group.isCollapsed() == collapsed)
			{
				return;
			}
			group.setCollapsed(collapsed);
			commit();
		}

		// Collapse now also drives the in-game grouped list, so redraw it too.
		fireChanged(true);
	}

	boolean isUngroupedCollapsed()
	{
		return ungroupedCollapsed;
	}

	void setUngroupedCollapsed(boolean collapsed)
	{
		if (!active || ungroupedCollapsed == collapsed)
		{
			return;
		}

		ungroupedCollapsed = collapsed;
		if (collapsed)
		{
			configManager.setRSProfileConfiguration(FriendGroupsConfig.GROUP, list.ungroupedCollapsedKey, true);
		}
		else
		{
			configManager.unsetRSProfileConfiguration(FriendGroupsConfig.GROUP, list.ungroupedCollapsedKey);
		}

		fireChanged(true);
	}

	boolean isOfflineCollapsed()
	{
		return offlineCollapsed;
	}

	void setOfflineCollapsed(boolean collapsed)
	{
		if (!active || offlineCollapsed == collapsed)
		{
			return;
		}

		offlineCollapsed = collapsed;
		if (collapsed)
		{
			configManager.setRSProfileConfiguration(FriendGroupsConfig.GROUP, list.offlineCollapsedKey, true);
		}
		else
		{
			configManager.unsetRSProfileConfiguration(FriendGroupsConfig.GROUP, list.offlineCollapsedKey);
		}

		fireChanged(true);
	}

	/** Where the Ungrouped section sits in the display order: groups shown before it, in [0, count]. */
	int ungroupedPosition()
	{
		final Integer order = ungroupedOrder;
		final int count = snapshot.size();
		return order == null ? count : Math.max(0, Math.min(order, count));
	}

	/**
	 * Applies a full display order given as tokens - group names plus, optionally, {@link #UNGROUPED}
	 * to say where the Ungrouped section goes. Used by the side panel after a drag. Groups missing
	 * from the tokens keep their relative order at the end; if no {@code UNGROUPED} token is present
	 * the Ungrouped position is left as it was.
	 */
	void applyOrder(List<String> tokens)
	{
		if (!active)
		{
			return;
		}

		synchronized (this)
		{
			applyTokens(tokens);
		}

		fireChanged(true);
	}

	/** Nudges a group one place up (delta -1) or down (delta +1), for the in-game header ops. */
	void moveGroup(String name, int delta)
	{
		moveToken(name, delta);
	}

	/** Nudges the Ungrouped section one place up (delta -1) or down (delta +1). */
	void moveUngrouped(int delta)
	{
		moveToken(UNGROUPED, delta);
	}

	private void moveToken(String token, int delta)
	{
		if (!active)
		{
			return;
		}

		synchronized (this)
		{
			final List<String> tokens = combinedTokens();
			final int from = indexOfToken(tokens, token);
			final int to = from + delta;
			if (from < 0 || to < 0 || to >= tokens.size())
			{
				return;
			}
			Collections.swap(tokens, from, to);
			applyTokens(tokens);
		}

		fireChanged(true);
	}

	/** The display order as tokens: group names, with {@link #UNGROUPED} at its current position. */
	private List<String> combinedTokens()
	{
		final int pos = ungroupedOrder == null ? groups.size() : Math.max(0, Math.min(ungroupedOrder, groups.size()));
		final List<String> tokens = new ArrayList<>(groups.size() + 1);
		for (int i = 0; i < groups.size(); i++)
		{
			if (i == pos)
			{
				tokens.add(UNGROUPED);
			}
			tokens.add(groups.get(i).getName());
		}
		if (pos >= groups.size())
		{
			tokens.add(UNGROUPED);
		}
		return tokens;
	}

	private static int indexOfToken(List<String> tokens, String token)
	{
		for (int i = 0; i < tokens.size(); i++)
		{
			if (UNGROUPED.equals(token) ? UNGROUPED.equals(tokens.get(i)) : token.equalsIgnoreCase(tokens.get(i)))
			{
				return i;
			}
		}
		return -1;
	}

	/** Reorders {@link #groups} and the Ungrouped position to match the given tokens. Caller holds the lock. */
	private void applyTokens(List<String> tokens)
	{
		final List<FriendGroup> reordered = new ArrayList<>(groups.size());
		Integer newPos = null;
		boolean sawUngrouped = false;
		for (String token : tokens)
		{
			if (UNGROUPED.equals(token))
			{
				newPos = reordered.size();
				sawUngrouped = true;
			}
			else
			{
				final FriendGroup group = find(token);
				if (group != null && !reordered.contains(group))
				{
					reordered.add(group);
				}
			}
		}

		// Preserve any group the tokens left out, so a stale drop can never drop groups.
		for (FriendGroup group : groups)
		{
			if (!reordered.contains(group))
			{
				reordered.add(group);
			}
		}

		groups.clear();
		groups.addAll(reordered);

		if (sawUngrouped)
		{
			// "Last" is stored as null so it stays last as groups are added later.
			ungroupedOrder = newPos >= groups.size() ? null : newPos;
		}
		commit();
	}

	void addMember(String groupName, String friend)
	{
		final String display = displayName(friend);
		if (!active || display == null)
		{
			return;
		}

		synchronized (this)
		{
			final FriendGroup group = find(groupName);
			if (group == null || group.contains(display))
			{
				return;
			}
			group.getMembers().add(display);
			commit();
		}

		fireChanged(true);
	}

	void removeMember(String groupName, String friend)
	{
		final String display = displayName(friend);
		if (!active || display == null)
		{
			return;
		}

		synchronized (this)
		{
			final FriendGroup group = find(groupName);
			if (group == null || !group.getMembers().removeIf(m -> key(m).equals(key(display))))
			{
				return;
			}
			commit();
		}

		fireChanged(true);
	}

	/** Drops a friend from every group, e.g. once they are no longer a friend. */
	void forgetFriend(String friend)
	{
		final String display = displayName(friend);
		if (!active || display == null)
		{
			return;
		}

		synchronized (this)
		{
			boolean dirty = false;
			for (FriendGroup group : groups)
			{
				dirty |= group.getMembers().removeIf(m -> key(m).equals(key(display)));
			}
			if (!dirty)
			{
				return;
			}
			commit();
		}

		fireChanged(true);
	}

	/** Follows a friend's display name change so their group membership survives it. */
	void renameFriend(String prevName, String currentName)
	{
		final String prev = displayName(prevName);
		final String current = displayName(currentName);
		if (!active || prev == null || current == null || key(prev).equals(key(current)))
		{
			return;
		}

		synchronized (this)
		{
			boolean dirty = false;
			for (FriendGroup group : groups)
			{
				final List<String> members = group.getMembers();
				for (int i = 0; i < members.size(); i++)
				{
					if (key(members.get(i)).equals(key(prev)))
					{
						members.set(i, current);
						dirty = true;
					}
				}
			}
			if (!dirty)
			{
				return;
			}
			log.debug("Migrated friend group membership: '{}' -> '{}'", prev, current);
			commit();
		}

		fireChanged(true);
	}

	private static String displayName(String friend)
	{
		if (friend == null)
		{
			return null;
		}
		final String display = Text.toJagexName(Text.removeTags(friend));
		return display.isEmpty() ? null : display;
	}

	private FriendGroup find(String name)
	{
		final int index = indexOf(name);
		return index < 0 ? null : groups.get(index);
	}

	private int indexOf(String name)
	{
		if (name == null)
		{
			return -1;
		}
		for (int i = 0; i < groups.size(); i++)
		{
			if (groups.get(i).getName().equalsIgnoreCase(name))
			{
				return i;
			}
		}
		return -1;
	}

	private void commit()
	{
		if (groups.isEmpty())
		{
			configManager.unsetRSProfileConfiguration(FriendGroupsConfig.GROUP, list.groupsKey);
		}
		else
		{
			configManager.setRSProfileConfiguration(FriendGroupsConfig.GROUP, list.groupsKey, gson.toJson(groups));
		}

		if (ungroupedOrder == null)
		{
			configManager.unsetRSProfileConfiguration(FriendGroupsConfig.GROUP, list.ungroupedOrderKey);
		}
		else
		{
			configManager.setRSProfileConfiguration(FriendGroupsConfig.GROUP, list.ungroupedOrderKey, ungroupedOrder);
		}
		reindex();
	}

	private void reindex()
	{
		final List<FriendGroup> copies = new ArrayList<>(groups.size());
		final Map<String, List<FriendGroup>> index = new HashMap<>();

		for (FriendGroup group : groups)
		{
			final FriendGroup copy = group.copy();
			copies.add(copy);

			for (String member : group.getMembers())
			{
				index.computeIfAbsent(key(member), k -> new ArrayList<>()).add(copy);
			}
		}

		index.replaceAll((k, v) -> Collections.unmodifiableList(v));
		membership = Collections.unmodifiableMap(index);
		snapshot = Collections.unmodifiableList(copies);
	}

	private void fireChanged(boolean inGameDirty)
	{
		for (Consumer<Boolean> listener : listeners)
		{
			listener.accept(inGameDirty);
		}
	}
}

