	String GROUP = "friend-groups";

	String SIDE_PANEL_PRIORITY = "sidePanelPriority";

	String HIDE_SIDE_PANEL = "hideSidePanel";

	@ConfigSection(
			name = "Friends list",
			description = "How your friend groups are shown in the in-game friends list.",
			position = 10
